package com.ke.ticketsystemke.service;
import com.ke.ticketsystemke.dto.*;import com.ke.ticketsystemke.entity.*;import com.ke.ticketsystemke.repository.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.time.temporal.*;import java.util.*;import java.util.function.*;import java.util.stream.*;
@Service public class WarrantyReportService{private static final ZoneId ZONE=ZoneId.of("Asia/Kolkata");private final WarrantyClaimRepository claims;private final WarrantyReplacementRepository replacements;private final WarrantyAttachmentRepository attachments;private final EmployeeRepository employees;private final AccessService access;private final WarrantyPendingActionCalculator pending;private final WarrantyDocumentRequirementService documents;
public WarrantyReportService(WarrantyClaimRepository c,WarrantyReplacementRepository r,WarrantyAttachmentRepository a,EmployeeRepository e,AccessService access,WarrantyPendingActionCalculator p,WarrantyDocumentRequirementService d){claims=c;replacements=r;attachments=a;employees=e;this.access=access;pending=p;documents=d;}
@Transactional(readOnly=true)public WarrantyReportResponse summary(WarrantyReportFilter f,String actor){Snapshot s=snapshot(f,actor);Map<String,Object>d=map();d.put("activeWarrantyCases",count(s,c->c.isActive()));d.put("actionRequired",count(s,c->c.isActive()&&!"NO_IMMEDIATE_ACTION".equals(code(c,s))));d.put("followUpDueToday",count(s,c->c.isActive()&&Objects.equals(c.getNextFollowUpDate(),today())));d.put("overdueFollowUps",count(s,c->c.isActive()&&c.getNextFollowUpDate()!=null&&c.getNextFollowUpDate().isBefore(today())));d.put("overdueVisits",count(s,c->visitOverdue(c)));d.put("documentsPending",count(s,c->requiredMissing(c,s)>0));d.put("awaitingResult",count(s,c->c.isActive()&&(c.getState()==WarrantyClaimState.VISIT_COMPLETED_AWAITING_RESULT||c.getState()==WarrantyClaimState.AWAITING_RESULT)));d.put("replacementPending",count(s,c->replacementPending(c,s)));d.put("readyToDeliver",count(s,c->ready(c)));d.put("awaitingCustomerDecision",count(s,c->c.isActive()&&(c.getState()==WarrantyClaimState.WARRANTY_REJECTED_AWAITING_DECISION||c.getState()==WarrantyClaimState.CUSTOMER_DECISION_PENDING)));return response(f,d);}
@Transactional(readOnly=true)public WarrantyReportResponse outcomes(WarrantyReportFilter f,String actor){Snapshot s=snapshot(f,actor);Map<String,Long> counts=new LinkedHashMap<>();for(WarrantyClaimResult r:WarrantyClaimResult.values())counts.put(r.name(),s.claims().stream().filter(c->c.getResult()==r&&eventInRange(c.getResolvedAt()!=null?date(c.getResolvedAt()):created(c),f)).count());long resolved=counts.entrySet().stream().filter(e->!e.getKey().equals("PENDING")).mapToLong(Map.Entry::getValue).sum();Map<String,Object>d=map();d.put("resolvedClaims",resolved);d.put("pendingClaims",counts.get("PENDING"));List<Map<String,Object>> rows=new ArrayList<>();for(var e:counts.entrySet())if(!e.getKey().equals("PENDING"))rows.add(Map.of("outcome",e.getKey(),"count",e.getValue(),"percentage",resolved==0?0.0:round(e.getValue()*100.0/resolved)));d.put("outcomes",rows);d.put("denominatorDefinition","Claims with a non-PENDING warranty result resolved in the selected period");return response(f,d);}
@Transactional(readOnly=true)public WarrantyReportResponse manufacturers(WarrantyReportFilter f,String actor){Snapshot s=snapshot(f,actor);Map<String,List<WarrantyClaim>> groups=s.claims().stream().collect(Collectors.groupingBy(c->blank(c.getManufacturerName())?"Not Provided":c.getManufacturerName().trim(),TreeMap::new,Collectors.toList()));List<Map<String,Object>> rows=new ArrayList<>();for(var g:groups.entrySet()){List<WarrantyClaim> cs=g.getValue(),resolved=cs.stream().filter(c->c.getResolvedAt()!=null).toList();Map<String,Object>m=map();m.put("manufacturer",g.getKey());m.put("totalClaims",cs.size());m.put("activeClaims",cs.stream().filter(WarrantyClaim::isActive).count());m.put("actionRequired",cs.stream().filter(c->c.isActive()&&!"NO_IMMEDIATE_ACTION".equals(code(c,s))).count());m.put("overdueFollowUps",cs.stream().filter(c->c.isActive()&&c.getNextFollowUpDate()!=null&&c.getNextFollowUpDate().isBefore(today())).count());m.put("overdueVisits",cs.stream().filter(this::visitOverdue).count());m.put("resolvedClaims",resolved.size());m.put("rejectedClaims",cs.stream().filter(c->c.getResult()==WarrantyClaimResult.WARRANTY_REJECTED).count());m.put("replacementCases",cs.stream().filter(c->c.getReplacementApprovedAt()!=null).count());m.put("averageResolutionDays",average(durations(resolved,c->created(c),c->date(c.getResolvedAt()))));m.put("oldestActiveClaimDays",cs.stream().filter(WarrantyClaim::isActive).mapToLong(this::activeDays).max().orElse(0));m.put("complaintToVisit",metric(durations(cs,c->c.getComplaintRegisteredDate(),WarrantyClaim::getActualVisitDate)));m.put("expectedVisitDelay",metric(cs.stream().filter(c->c.getExpectedVisitDate()!=null&&c.getActualVisitDate()!=null).mapToLong(c->Math.max(0,ChronoUnit.DAYS.between(c.getExpectedVisitDate(),c.getActualVisitDate()))).boxed().toList()));m.put("complaintToResolution",metric(durations(resolved,WarrantyClaim::getComplaintRegisteredDate,c->date(c.getResolvedAt()))));m.put("totalResolution",metric(durations(resolved,this::created,c->date(c.getResolvedAt()))));rows.add(m);}rows.sort(Comparator.comparingLong((Map<String,Object>x)->((Number)x.get("activeClaims")).longValue()).reversed());return response(f,Map.of("manufacturers",rows));}
@Transactional(readOnly=true)public WarrantyReportResponse resolutionTimes(WarrantyReportFilter f,String actor){Snapshot s=snapshot(f,actor);List<WarrantyClaim> resolved=s.claims().stream().filter(c->c.getResolvedAt()!=null&&eventInRange(date(c.getResolvedAt()),f)).toList();List<Long> all=durations(resolved,this::created,c->date(c.getResolvedAt()));Map<String,Object>d=map();d.put("overall",durationSummary(all));List<Map<String,Object>> by=new ArrayList<>();for(WarrantyClaimResult r:WarrantyClaimResult.values())if(r!=WarrantyClaimResult.PENDING){List<Long>x=durations(resolved.stream().filter(c->c.getResult()==r).toList(),this::created,c->date(c.getResolvedAt()));by.add(Map.of("outcome",r.name(),"metrics",durationSummary(x)));}d.put("byOutcome",by);d.put("buckets",buckets(all));d.put("oldestActiveClaimDays",s.claims().stream().filter(WarrantyClaim::isActive).mapToLong(this::activeDays).max().orElse(0));return response(f,d);}
@Transactional(readOnly=true)public WarrantyReportResponse followUpVisits(WarrantyReportFilter f,String actor){Snapshot s=snapshot(f,actor);Map<String,Object>d=map();d.put("followUpsDue",count(s,c->c.isActive()&&c.getNextFollowUpDate()!=null&&!c.getNextFollowUpDate().isAfter(today())));d.put("followUpsOverdue",count(s,c->c.isActive()&&c.getNextFollowUpDate()!=null&&c.getNextFollowUpDate().isBefore(today())));d.put("visitsScheduled",count(s,c->c.getExpectedVisitDate()!=null&&eventInRange(c.getExpectedVisitDate(),f)));d.put("visitsCompleted",count(s,c->c.getActualVisitDate()!=null&&eventInRange(c.getActualVisitDate(),f)));d.put("visitsOverdue",count(s,this::visitOverdue));d.put("engineerNoShowCases",count(s,c->c.getVisitOutcome()==WarrantyVisitOutcome.ENGINEER_DID_NOT_VISIT));List<Long> delays=s.claims().stream().filter(c->c.getExpectedVisitDate()!=null&&c.getActualVisitDate()!=null).map(c->Math.max(0,ChronoUnit.DAYS.between(c.getExpectedVisitDate(),c.getActualVisitDate()))).toList();d.put("visitDelay",metric(delays));Map<String,Object>unavailable=map();unavailable.put("average",null);unavailable.put("sampleSize",0);unavailable.put("available",false);unavailable.put("reason","A specific follow-up completion milestone is not recorded");d.put("followUpDelay",unavailable);return response(f,d);}
@Transactional(readOnly=true)public WarrantyReportResponse replacement(WarrantyReportFilter f,String actor){Snapshot s=snapshot(f,actor);List<WarrantyReplacement> rs=s.allReplacements();Map<String,Object>d=map();d.put("approved",count(s,c->c.getReplacementApprovedAt()!=null&&eventInRange(date(c.getReplacementApprovedAt()),f)));d.put("received",rs.stream().filter(r->r.getReplacementReceivedDate()!=null&&eventInRange(r.getReplacementReceivedDate(),f)).count());d.put("awaitingProduct",count(s,c->c.getState()==WarrantyClaimState.REPLACEMENT_APPROVED_AWAITING_PRODUCT));d.put("awaitingDelivery",count(s,c->c.getResult()==WarrantyClaimResult.REPLACEMENT_DONE&&c.getState()==WarrantyClaimState.DELIVERY_PENDING));d.put("delivered",rs.stream().filter(r->r.getReplacementGivenToCustomerDate()!=null&&eventInRange(r.getReplacementGivenToCustomerDate(),f)).count());List<Long>a2r=new ArrayList<>(),r2d=new ArrayList<>();for(WarrantyReplacement r:rs){WarrantyClaim c=r.getWarrantyClaim();if(c.getReplacementApprovalDate()!=null&&r.getReplacementReceivedDate()!=null)a2r.add(Math.max(0,ChronoUnit.DAYS.between(c.getReplacementApprovalDate(),r.getReplacementReceivedDate())));if(r.getReplacementReceivedDate()!=null&&r.getReplacementGivenToCustomerDate()!=null)r2d.add(Math.max(0,ChronoUnit.DAYS.between(r.getReplacementReceivedDate(),r.getReplacementGivenToCustomerDate())));}d.put("approvalToReceipt",metric(a2r));d.put("receiptToDelivery",metric(r2d));d.put("serialOverridesUsed",rs.stream().filter(r->r.getSerialNumberOverrideReason()!=null).count());d.put("supersededRecords",rs.stream().filter(r->!r.isActive()).count());return response(f,d);}
@Transactional(readOnly=true)public WarrantyReportResponse owners(WarrantyReportFilter f,String actor){Snapshot s=snapshot(f,actor);Map<String,List<WarrantyClaim>> groups=s.claims().stream().collect(Collectors.groupingBy(c->blank(c.getWarrantyOwnerEmployeeId())?"":c.getWarrantyOwnerEmployeeId()));List<Map<String,Object>> rows=new ArrayList<>();for(var g:groups.entrySet()){String id=g.getKey();List<WarrantyClaim>cs=g.getValue();Map<String,Object>m=map();m.put("ownerId",id);m.put("ownerName",id.isEmpty()?"Unassigned":s.ownerNames().getOrDefault(id.toLowerCase(Locale.ROOT),id));m.put("activeClaims",cs.stream().filter(WarrantyClaim::isActive).count());m.put("actionRequired",cs.stream().filter(c->c.isActive()&&!"NO_IMMEDIATE_ACTION".equals(code(c,s))).count());m.put("followUpDue",cs.stream().filter(c->c.isActive()&&c.getNextFollowUpDate()!=null&&!c.getNextFollowUpDate().isAfter(today())).count());m.put("overdueVisits",cs.stream().filter(this::visitOverdue).count());m.put("awaitingResult",cs.stream().filter(c->c.isActive()&&(c.getState()==WarrantyClaimState.VISIT_COMPLETED_AWAITING_RESULT||c.getState()==WarrantyClaimState.AWAITING_RESULT)).count());m.put("replacementPending",cs.stream().filter(c->replacementPending(c,s)).count());m.put("readyToDeliver",cs.stream().filter(this::ready).count());m.put("oldestActiveClaimDays",cs.stream().filter(WarrantyClaim::isActive).mapToLong(this::activeDays).max().orElse(0));rows.add(m);}return response(f,Map.of("owners",rows));}
@Transactional(readOnly=true)public WarrantyReportResponse documentReadiness(WarrantyReportFilter f,String actor){Snapshot s=snapshot(f,actor);Map<String,Object>d=map();d.put("claimsMissingRequired",count(s,c->requiredMissing(c,s)>0));d.put("claimsUsingBillOverride",count(s,c->c.getBillDocumentOverrideReason()!=null));for(WarrantyAttachmentCategory c:List.of(WarrantyAttachmentCategory.BILL_IMAGE,WarrantyAttachmentCategory.WARRANTY_CARD_IMAGE,WarrantyAttachmentCategory.MANUFACTURER_SERVICE_SLIP,WarrantyAttachmentCategory.REPLACEMENT_PROOF,WarrantyAttachmentCategory.REPLACEMENT_SERIAL_NUMBER_IMAGE))d.put(c.name(),s.categories().values().stream().filter(x->x.contains(c)).count());d.put("recommendedMissing",s.claims().stream().mapToLong(c->recommendedMissing(c,s)).sum());return response(f,d);}
@Transactional(readOnly=true)public WarrantyReportResponse trends(WarrantyReportFilter f,String actor){Snapshot s=snapshot(f,actor);String grouping=grouping(f);List<LocalDate> periods=periods(f,grouping);Map<LocalDate,Map<String,Long>> data=new LinkedHashMap<>();for(LocalDate p:periods)data.put(p,new LinkedHashMap<>(Map.of("claimsCreated",0L,"complaintsRegistered",0L,"claimsResolved",0L,"replacementsCompleted",0L,"warrantyRejections",0L)));for(WarrantyClaim c:s.claims()){inc(data,key(created(c),grouping),"claimsCreated");inc(data,key(c.getComplaintRegisteredDate(),grouping),"complaintsRegistered");inc(data,key(c.getResolvedAt()==null?null:date(c.getResolvedAt()),grouping),"claimsResolved");if(c.getResult()==WarrantyClaimResult.REPLACEMENT_DONE)inc(data,key(c.getResolvedAt()==null?null:date(c.getResolvedAt()),grouping),"replacementsCompleted");inc(data,key(c.getWarrantyRejectedAt()==null?null:date(c.getWarrantyRejectedAt()),grouping),"warrantyRejections");}List<Map<String,Object>> rows=new ArrayList<>();data.forEach((p,m)->{Map<String,Object>x=map();x.put("period",p);x.putAll(m);rows.add(x);});return response(f,Map.of("grouping",grouping,"periods",rows));}
@Transactional(readOnly=true)public WarrantyReportResponse options(WarrantyReportFilter f,String actor){Snapshot s=snapshot(f,actor);Map<String,Object>d=map();d.put("manufacturers",values(s.claims(),WarrantyClaim::getManufacturerName));d.put("owners",s.ownerNames());d.put("categories",values(s.claims(),c->category(c.getTicket())));d.put("results",Arrays.stream(WarrantyClaimResult.values()).map(Enum::name).toList());d.put("states",Arrays.stream(WarrantyClaimState.values()).map(Enum::name).toList());return response(f,d);}
private Snapshot snapshot(WarrantyReportFilter f,String actor){authorize(actor);validate(f);List<WarrantyClaim> all=claims.findAllForTracker();List<WarrantyClaim> filtered=all.stream().filter(c->highLevel(c,f)).toList();if(filtered.isEmpty())return new Snapshot(List.of(),Map.of(),List.of(),Map.of(),Map.of());List<Long>ids=filtered.stream().map(WarrantyClaim::getId).toList();List<WarrantyReplacement> rs=replacements.findByWarrantyClaim_IdIn(ids);Map<Long,WarrantyReplacement>active=rs.stream().filter(WarrantyReplacement::isActive).collect(Collectors.toMap(r->r.getWarrantyClaim().getId(),Function.identity()));Map<Long,Set<WarrantyAttachmentCategory>>cats=new HashMap<>();for(Object[]x:attachments.findActiveCategoriesByClaimIds(ids))cats.computeIfAbsent((Long)x[0],k->EnumSet.noneOf(WarrantyAttachmentCategory.class)).add((WarrantyAttachmentCategory)x[1]);Set<String>owners=filtered.stream().map(WarrantyClaim::getWarrantyOwnerEmployeeId).filter(Objects::nonNull).map(x->x.toLowerCase(Locale.ROOT)).collect(Collectors.toSet());Map<String,String>names=employees.findByEmployeeIdLowercaseIn(owners).stream().collect(Collectors.toMap(e->e.getEmployeeId().toLowerCase(Locale.ROOT),Employee::getName));return new Snapshot(filtered,active,rs,cats,names);}
private boolean highLevel(WarrantyClaim c,WarrantyReportFilter f){Ticket t=c.getTicket();if(!eventInRange(created(c),f))return false;if(f.getManufacturer()!=null&&!eq(c.getManufacturerName(),f.getManufacturer()))return false;if(f.getOwner()!=null&&!eq(c.getWarrantyOwnerEmployeeId(),f.getOwner()))return false;if(f.getCategory()!=null&&!eq(category(t),f.getCategory()))return false;if(f.getResult()!=null&&!eq(c.getResult().name(),f.getResult()))return false;if(f.getState()!=null&&!eq(c.getState().name(),f.getState()))return false;if(f.getTicketStatus()!=null&&!eq(status(t),f.getTicketStatus()))return false;return f.getActive()==null||f.getActive()==c.isActive();}
private void validate(WarrantyReportFilter f){if(f.getFrom()==null||f.getTo()==null||f.getTo().isBefore(f.getFrom()))bad("Valid from and to dates are required");if(ChronoUnit.DAYS.between(f.getFrom(),f.getTo())>1826)bad("Reporting range cannot exceed five years");if(f.getGrouping()!=null&&!Set.of("DAILY","WEEKLY","MONTHLY").contains(f.getGrouping()))bad("Unsupported trend grouping");}private WarrantyReportResponse response(WarrantyReportFilter f,Map<String,Object>d){return new WarrantyReportResponse(f.getFrom(),f.getTo(),ZONE.getId(),OffsetDateTime.now(ZONE),d);}private long count(Snapshot s,Predicate<WarrantyClaim>p){return s.claims().stream().filter(p).filter(c->eventInRange(created(c),new WarrantyReportFilterRange(s,c))).count();}private boolean eventInRange(LocalDate d,WarrantyReportFilter f){return d!=null&&!d.isBefore(f.getFrom())&&!d.isAfter(f.getTo());}private boolean eventInRange(LocalDate d,WarrantyReportFilterRange ignored){return d!=null;}private record WarrantyReportFilterRange(Snapshot s,WarrantyClaim c){}
private String code(WarrantyClaim c,Snapshot s){return pending.calculate(c,s.activeReplacements().get(c.getId())).code();}private boolean visitOverdue(WarrantyClaim c){return c.isActive()&&c.getExpectedVisitDate()!=null&&c.getExpectedVisitDate().isBefore(today())&&c.getActualVisitDate()==null;}private boolean replacementPending(WarrantyClaim c,Snapshot s){return c.isActive()&&(c.getState()==WarrantyClaimState.REPLACEMENT_APPROVED_AWAITING_PRODUCT||c.getState()==WarrantyClaimState.REPLACEMENT_RECEIVED||c.getState()==WarrantyClaimState.DELIVERY_PENDING&&c.getResult()==WarrantyClaimResult.REPLACEMENT_DONE||"COMPLETE_REPLACEMENT_DETAILS".equals(code(c,s)));}private boolean ready(WarrantyClaim c){return c.isActive()&&(c.getState()==WarrantyClaimState.MANUFACTURER_REPAIR_COMPLETED||c.getState()==WarrantyClaimState.REPLACEMENT_RECEIVED||c.getState()==WarrantyClaimState.DELIVERY_PENDING);}private int requiredMissing(WarrantyClaim c,Snapshot s){return documents.billRuleApplies(c)&&!s.categories().getOrDefault(c.getId(),Set.of()).contains(WarrantyAttachmentCategory.BILL_IMAGE)?1:0;}private int recommendedMissing(WarrantyClaim c,Snapshot s){Set<WarrantyAttachmentCategory>p=s.categories().getOrDefault(c.getId(),Set.of());int n=0;if(!p.contains(WarrantyAttachmentCategory.WARRANTY_CARD_IMAGE))n++;if(!p.contains(WarrantyAttachmentCategory.PRODUCT_SERIAL_NUMBER_IMAGE))n++;if(c.getManufacturerComplaintNumber()!=null&&!p.contains(WarrantyAttachmentCategory.MANUFACTURER_SERVICE_SLIP))n++;if(s.activeReplacements().containsKey(c.getId())&&!p.contains(WarrantyAttachmentCategory.REPLACEMENT_PROOF))n++;return n;}
private List<Long>durations(Collection<WarrantyClaim>cs,Function<WarrantyClaim,LocalDate>start,Function<WarrantyClaim,LocalDate>end){return cs.stream().filter(c->start.apply(c)!=null&&end.apply(c)!=null).map(c->Math.max(0,ChronoUnit.DAYS.between(start.apply(c),end.apply(c)))).toList();}private Map<String,Object>metric(List<Long>x){Map<String,Object>m=map();m.put("average",average(x));m.put("median",median(x));m.put("sampleSize",x.size());return m;}private Map<String,Object>durationSummary(List<Long>x){Map<String,Object>m=metric(x);m.put("fastest",x.stream().min(Long::compareTo).orElse(null));m.put("longest",x.stream().max(Long::compareTo).orElse(null));return m;}private Double average(List<Long>x){return x.isEmpty()?null:round(x.stream().mapToLong(Long::longValue).average().orElse(0));}private Double median(List<Long>x){if(x.isEmpty())return null;List<Long>s=x.stream().sorted().toList();int n=s.size();return n%2==1?s.get(n/2).doubleValue():round((s.get(n/2-1)+s.get(n/2))/2.0);}private List<Map<String,Object>>buckets(List<Long>x){long[][]ranges={{0,2},{3,7},{8,14},{15,30},{31,60},{61,Long.MAX_VALUE}};String[]labels={"0–2 days","3–7 days","8–14 days","15–30 days","31–60 days","More than 60 days"};return java.util.stream.IntStream.range(0,ranges.length).mapToObj(i->{long n=x.stream().filter(v->v>=ranges[i][0]&&v<=ranges[i][1]).count();return Map.<String,Object>of("label",labels[i],"count",n,"percentage",x.isEmpty()?0.0:round(n*100.0/x.size()));}).toList();}
private String grouping(WarrantyReportFilter f){if(f.getGrouping()!=null)return f.getGrouping();long days=ChronoUnit.DAYS.between(f.getFrom(),f.getTo())+1;return days<=31?"DAILY":days<=180?"WEEKLY":"MONTHLY";}private List<LocalDate>periods(WarrantyReportFilter f,String g){List<LocalDate>out=new ArrayList<>();LocalDate p=key(f.getFrom(),g),end=key(f.getTo(),g);while(!p.isAfter(end)){out.add(p);p=g.equals("DAILY")?p.plusDays(1):g.equals("WEEKLY")?p.plusWeeks(1):p.plusMonths(1);}return out;}private LocalDate key(LocalDate d,String g){if(d==null)return null;if(g.equals("WEEKLY"))return d.with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));if(g.equals("MONTHLY"))return d.withDayOfMonth(1);return d;}private void inc(Map<LocalDate,Map<String,Long>>d,LocalDate p,String k){if(p!=null&&d.containsKey(p))d.get(p).compute(k,(a,v)->v==null?1:v+1);}private long activeDays(WarrantyClaim c){return Math.max(0,ChronoUnit.DAYS.between(created(c),today()));}private LocalDate created(WarrantyClaim c){Instant i=c.getMarkedWarrantyAt()!=null?c.getMarkedWarrantyAt():c.getCreatedAt();return i==null?null:date(i);}private LocalDate date(Instant i){return i.atZone(ZONE).toLocalDate();}private LocalDate today(){return LocalDate.now(ZONE);}private String category(Ticket t){return t.getCategoryRecord()!=null?t.getCategoryRecord().getDisplayName():t.getCategory()==null?null:t.getCategory().name();}private String status(Ticket t){return t.getStatusRecord()!=null?t.getStatusRecord().getDisplayName():t.getStatus().name();}private List<String>values(List<WarrantyClaim>c,Function<WarrantyClaim,String>f){return c.stream().map(f).filter(x->!blank(x)).map(String::trim).distinct().sorted(String.CASE_INSENSITIVE_ORDER).toList();}private boolean eq(String a,String b){return a!=null&&a.equalsIgnoreCase(b.trim());}private boolean blank(String s){return s==null||s.isBlank();}private Double round(double v){return Math.round(v*10.0)/10.0;}private Object nullValue(){return null;}private Map<String,Object>map(){return new LinkedHashMap<>();}private void authorize(String a){access.requireAllowed(a,AccessKey.VIEW_TICKETS);access.requireAllowed(a,AccessKey.VIEW_WARRANTY_REPORTS);}private void bad(String m){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private record Snapshot(List<WarrantyClaim>claims,Map<Long,WarrantyReplacement>activeReplacements,List<WarrantyReplacement>allReplacements,Map<Long,Set<WarrantyAttachmentCategory>>categories,Map<String,String>ownerNames){}
}
